<script setup>
import { onMounted, reactive, ref } from 'vue'
import { BadgePercent, LoaderCircle, RefreshCw, Search } from 'lucide-vue-next'
import BaseModal from '../components/BaseModal.vue'
import { auditMerchantCoupon, getMerchantCoupon, getMerchantCoupons } from '../services/merchantAudit.js'
import { showToast } from '../utils.js'
const rows=ref([]), total=ref(0), loading=ref(false), selected=ref(null), open=ref(false), reason=ref(''), processing=ref(false); const filters=reactive({status:'PENDING',page:1,size:20})
const meta=s=>({PENDING:['待办理','warning'],APPROVED:['已同意','success'],REJECTED:['已拒绝','danger']}[s]||[s,''])
async function load(){loading.value=true;try{const d=await getMerchantCoupons(filters);rows.value=d.records||[];total.value=Number(d.total||0)}catch(e){showToast(e.message)}finally{loading.value=false}}
async function detail(row){open.value=true;selected.value=row;reason.value=row.rejectReason||'';try{selected.value=await getMerchantCoupon(row.couponId)}catch(e){showToast(e.message)}}
async function audit(result){if(result==='REJECTED'&&reason.value.trim().length<2)return showToast('拒绝时请填写至少 2 个字的原因');processing.value=true;try{await auditMerchantCoupon(selected.value.couponId,result,reason.value.trim());showToast(result==='APPROVED'?'优惠券审核通过并进入上线判定':'优惠券已拒绝，商家可修改重提');open.value=false;await load()}catch(e){showToast(e.message)}finally{processing.value=false}}
onMounted(load)
</script>
<template><div class="page"><div class="page-head"><div><div class="eyebrow"><BadgePercent/> MERCHANT BENEFITS</div><h1>商家优惠审核</h1><p>审核价格、拼单人数、有效期、适用门店与使用规则，通过后才能进入 App 市场。</p></div><button class="btn" @click="load"><LoaderCircle v-if="loading" class="spin"/><RefreshCw v-else/>刷新队列</button></div><section class="panel"><div class="panel-head"><div><h2>优惠券审核队列</h2><p>共 {{ total }} 条</p></div><span class="endpoint">GET /v1/admin/merchant-coupons</span></div><div class="toolbar"><select v-model="filters.status" class="field" @change="load"><option value="">全部状态</option><option value="PENDING">待办理</option><option value="APPROVED">已同意</option><option value="REJECTED">已拒绝</option></select><button class="btn primary" @click="load"><Search/>查询</button></div><div v-if="!rows.length" class="empty-note"><BadgePercent/><p>当前状态下没有待审核优惠</p></div><div v-else class="table-wrap"><table><thead><tr><th>优惠券</th><th>商家 / 门店</th><th>价格</th><th>拼单规则</th><th>有效期</th><th>审核状态</th><th>操作</th></tr></thead><tbody><tr v-for="row in rows" :key="row.couponId"><td><b>{{ row.couponName }}</b><small>{{ row.category }} · {{ row.couponId }}</small></td><td><b>{{ row.merchantName }}</b><small>{{ row.storeName }}</small></td><td>¥{{ row.salePrice }} / <small>¥{{ row.originalPrice }}</small></td><td>{{ row.groupEnabled ? `${row.groupPeople}人 / ${row.groupTimeoutHours}小时` : '不拼单' }}</td><td>{{ row.publishTime }}<br><small>至 {{ row.expireTime }}</small></td><td><span class="status" :class="meta(row.auditStatus)[1]">{{ meta(row.auditStatus)[0] }}</span></td><td><button class="btn sm" @click="detail(row)">{{ row.auditStatus==='PENDING'?'办理':'查看' }}</button></td></tr></tbody></table></div></section><BaseModal :open="open" title="优惠券审核" @close="open=false"><template v-if="selected"><div class="detail-grid"><div class="detail-item"><small>优惠券</small><b>{{ selected.couponName }}</b></div><div class="detail-item"><small>商家 / 门店</small><b>{{ selected.merchantName }} / {{ selected.storeName }}</b></div><div class="detail-item"><small>售价 / 原价</small><b>¥{{ selected.salePrice }} / ¥{{ selected.originalPrice }}</b></div><div class="detail-item"><small>库存 / 限购</small><b>{{ selected.stock }} / {{ selected.limitCount }}</b></div><div class="detail-item"><small>拼单规则</small><b>{{ selected.groupEnabled ? `${selected.groupPeople}人成团，${selected.groupTimeoutHours}小时` : '未开启' }}</b></div></div><p>{{ selected.description }}</p><div class="notice-box">使用须知：{{ selected.useInstructions }}</div><div v-if="selected.auditStatus==='PENDING'" class="form-group"><label>拒绝原因（拒绝时必填）</label><textarea v-model="reason" class="field" maxlength="255"></textarea></div></template><template #footer><button class="btn" @click="open=false">关闭</button><template v-if="selected?.auditStatus==='PENDING'"><button class="btn danger" :disabled="processing" @click="audit('REJECTED')">拒绝</button><button class="btn success solid" :disabled="processing" @click="audit('APPROVED')">同意</button></template></template></BaseModal></div></template>
